import openpyxl
s=openpyxl.load_workbook('seeds/Northstar_Forecast_Starter.xlsx'); o=openpyxl.load_workbook('output/Northstar_Forecast_Completed.xlsx')
n=0;bad=[]
for ws in s:
  wo=o[ws.title]
  for row in ws.iter_rows(min_row=1,max_row=ws.max_row,max_col=19):
    for c in row:
      co=wo[c.coordinate]
      if c.value!=co.value:
        n+=1
        if c.fill.fgColor.rgb not in ('FFFFF2CC',) : bad.append((ws.title,c.coordinate,c.fill.fgColor.rgb))
      for a in ('font','fill','border','number_format','alignment','protection'):
        if repr(getattr(c,a))!=repr(getattr(co,a)): bad.append((ws.title,c.coordinate,a))
      if (c.comment and c.comment.text)!=(co.comment and co.comment.text): bad.append((ws.title,c.coordinate,'comment'))
print('changed',n,'issues',bad[:10],len(bad))
